 add(6,[["Sonido diegético","Sonido que pertenece al mundo de la historia y que los personajes pueden oír."],["Contrapunto","Relación en la que sonido e imagen dicen algo distinto y generan un sentido nuevo."],["Narración de contrapunto","Narración que dice algo opuesto a lo que muestra la imagen."],["Efecto de sonido contextual","Efecto que viene de una fuente visible y se reproduce tal cual."],["Efecto de sonido narrativo","Efecto que añade a la escena información que la imagen no muestra."]],[["Se ve una cama vacía de hospital mientras suena música alegre. ¿Qué relación sonido-imagen es?",["Paralelo","Contrapunto","Redundancia","Silencio"],1,"Cada elemento aporta algo distinto y crea un sentido nuevo."],["Unas gaviotas indican que estamos en un puerto. ¿Qué función tiene ese efecto?",["Ubicar el lugar","Marcar el ritmo","Simbolizar","Dar contrapunto"],0,"El sonido sitúa la escena en un lugar."]]);
